import 'dart:io';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'exercise_figure_3d_baseline.dart';
import 'fifa_baseline_view.dart';
void main() {
  testWidgets('FIFA exposes ten selectable parts instead of a moments carousel', (tester) async {
    final catalog = Figure3DCatalog.fromJsonString(File('build/qa/035/baseline-8ef2df4.json').readAsStringSync());
    await tester.pumpWidget(MaterialApp(home: Figure3DFullScreen(figure: catalog.forExercise('Calentamiento tipo FIFA 11+')!)));
    expect(find.byType(DropdownButton<int>), findsOneWidget);
    expect(find.text('Parte 1 de 10'), findsOneWidget);
    expect(find.byType(ChoiceChip), findsNothing);
  });
  testWidgets('changing fullscreen figure resets the requested initial pose and stops playback', (tester) async {
    final catalog = Figure3DCatalog.fromJsonString(File('build/qa/035/baseline-8ef2df4.json').readAsStringSync());
    Future<void> open(String name, double initial) => tester.pumpWidget(MaterialApp(
      home: Figure3DFullScreen(figure: catalog.forExercise(name)!, initialProgress: initial)));
    await open('Barca / V-sit', .17);
    await tester.ensureVisible(find.text('Movimiento'));
    await tester.tap(find.text('Movimiento').hitTestable());
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 700));
    await open('Dominadas', .35);
    final painter = tester.widgetList<CustomPaint>(find.byType(CustomPaint))
      .map((widget) => widget.painter).whereType<Figure3DPainter>().single;
    expect(painter.progress, closeTo(.35, 1e-8));
    expect(find.text('Pausa'), findsNothing);
  });
}
